<template>
  <v-container class="mt-4">
    <v-overlay :value="overlay">
      <v-progress-circular
        color="primary"
        indeterminate
        size="50"
      ></v-progress-circular>
    </v-overlay>
    <v-navigation-drawer
      app
      class="primary darken-1 white--text"
      clipped
      permanent
      right
      style="z-index: 3;"
    >
      <v-list class="white--text">
        <v-list-item v-if="practitioner">
          <v-btn
            class="primary"
            dark
            @click="$router.push('/resource/view/student/' + practitioner)"
          >
            <v-icon light left>mdi-eye</v-icon>
            <span>View Student</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn
            :disabled="!canFinanceReview"
            class="success"
            dark
            @click="approvalDialog = true"
          >
            <!-- <v-btn class="success" dark @click="approvalDialog = true"> -->
            <v-icon light left>mdi-check-decagram</v-icon>
            <span>Finance Director Review</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn
            :disabled="!canTaalimReview"
            class="success"
            dark
            @click="approvalDialog = true"
          >
            <!-- <v-btn class="success" dark @click="approvalDialog = true"> -->
            <v-icon light left>mdi-check-decagram</v-icon>
            <span>Taalim Director Review</span>
          </v-btn>
        </v-list-item>
      </v-list>
    </v-navigation-drawer>
    <v-dialog
      v-model="approvalDialog"
      persistent
      max-width="500px"
      transition="dialog-transition"
    >
      <v-card>
        <v-toolbar
          color="primary"
          class="darken-1 white--text text-uppercase font-weight-bold"
          dark
        >
          Approve/Reject Registration
          <v-spacer></v-spacer>
          <v-btn icon color="white" @click="approvalDialog = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </v-toolbar>
        <v-card-text>
          <v-select
            :items="statuses"
            v-model="status"
            label="Status"
            outlined
            dense
            class="ma-2"
            hide-details
            clearable
          ></v-select>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="success" :disabled="!status" @click="save">Save</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
    <fhir-page-view
      :id="queries.id"
      page="itsf-registration-application"
      :key="key"
      :showDrawer="false"
    />
  </v-container>
</template>

<script>
export default {
  props: ["queries"],
  data: function() {
    return {
      key: 0,
      financeReview: {},
      taalimReview: {},
      taalimReviewId: "",
      financeReviewId: "",
      statusText: "",
      status: "",
      regStatus: "",
      statuses: [
        {
          text: "Approve",
          value: "approved",
        },
        {
          text: "Reject",
          value: "rejected",
        },
        {
          text: "Pending",
          value: "pending",
        },
      ],
      payments: [],
      approvalDialog: false,
      rows: {
        fake: false,
      },
      overlay: false,
    };
  },
  computed: {
    role() {
      let role = this.$store.state.user.obj.resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-assign-role"
        );
      }).valueReference.reference;
      return role.split("/")[1];
    },
    canFinanceReview() {
      if (
        this.financeReview.code != "approved" &&
        this.role === "itsf-admin-finance-role"
      ) {
        return true;
      }
      return false;
    },
    canTaalimReview() {
      if (
        this.financeReview.code == "approved" &&
        this.taalimReview.code !== "approved" &&
        this.role === "itsf-taalim-role"
      ) {
        return true;
      }
      return false;
    },
  },
  methods: {
    getReviewStatuses() {
      return new Promise((resolve) => {
        fetch("/fhir/Basic/" + this.queries.id)
          .then((response) => {
            response
              .json()
              .then((response) => {
                this.taalimReview = response.extension.find((ext) => {
                  return (
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/taalim-status"
                  );
                })?.valueCoding;
                this.financeReview = response.extension.find((ext) => {
                  return (
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/finance-status"
                  );
                })?.valueCoding;
                this.practitioner = response.extension.find((ext) => {
                  return (
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
                  );
                })?.valueReference?.reference;
                if (this.practitioner) {
                  this.practitioner = this.practitioner.split("/")[1];
                }
                if (!this.financeReview) {
                  this.financeReview = {
                    code: "pending",
                  };
                }
                if (!this.taalimReview) {
                  this.taalimReview = {
                    code: "pending",
                  };
                }
                if (
                  this.financeReview &&
                  this.financeReview?.code != "approved"
                ) {
                  this.status = this.financeReview.code;
                } else if (
                  this.financeReview &&
                  this.financeReview?.code === "pending"
                ) {
                  this.statusText = "Waiting Finance Director Approval";
                }
                if (
                  this.financeReview?.code == "approved" &&
                  this.taalimReview?.code !== "approved"
                ) {
                  this.status = this.taalimReview.code;
                } else if (this.taalimReview?.code === "pending") {
                  this.statusText = "Waiting Finance Director Approval";
                }
                this.regStatus = this.status;
                resolve();
              })
              .catch(() => {
                resolve();
              });
          })
          .catch(() => {
            resolve();
          });
      });
    },
    save() {
      this.overlay = true;
      this.approvalDialog = false;
      let body = {
        status: this.status,
        id: this.queries.id,
        practitioner: this.queries.practitioner,
        role: this.role,
      };
      fetch("/site/student/new_registration_approval", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        redirect: "manual",
        body: JSON.stringify(body),
      }).then((response) => {
        if (response.ok) {
          this.key += 1;
          this.getReviewStatuses().then(() => {
            this.overlay = false;
          });
          this.$store.commit("setMessage", {
            type: "success",
            text: "Registration Processed Successfully",
          });
        } else {
          this.$store.commit("setMessage", {
            type: "error",
            text: "Failed to process registration",
          });
        }
      });
    },
    hasTask(task) {
      return (
        this.$store.state.user.obj.permissions &&
        this.$store.state.user.obj.permissions.special &&
        this.$store.state.user.obj.permissions.special.special &&
        this.$store.state.user.obj.permissions.special.special.id &&
        this.$store.state.user.obj.permissions.special.special.id[task]
      );
    },
  },
  created() {
    this.overlay = true;
    this.getReviewStatuses().then(() => {
      this.overlay = false;
    });
  },
  components: {
    "fhir-page-view": () => import("@/views/fhir-page-view"),
  },
};
</script>
